-- Robotics/Embedded/IoT pathway ("Vector Division") Act 16 -- "Embedded
-- Security" content, under world-vec-embedded-security (already inserted
-- separately). 1 campaign, 2 operations, 12 missions (11 lessons + boss),
-- following the same campaigns -> operations -> missions -> dialogue ->
-- objectives -> challenges -> hints pattern as every other pathway. No new
-- ChallengeType needed -- reuses story_dialogue, multiple_choice,
-- drag_and_drop, investigation, interactive_diagram, browser_simulation
-- (generic console fallback) and boss_encounter. Arc III's fleet audit
-- (Act 15) revealed thousands of matching embedded controllers across
-- Nexus; Act 16 is the security audit that follows -- and the very first
-- device it checks fails, not because it was attacked, but because nobody
-- ever enforced a process that could have caught an unauthorized generic
-- replacement part in the first place.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-embedded-security', 'world-vec-embedded-security', 'embedded-security', '3D - Embedded Security', 'Learn to secure a fleet of embedded controllers end to end -- threat modeling, secure boot, firmware signing, device secrets, hardware root-of-trust, TLS on constrained devices, certificate provisioning, key rotation, debug-port risk, physical attack awareness, and a secure update pipeline -- while Vector Division audits the fleet Act 15 finally made visible, and Sera Holt''s security audit is finally taken seriously.', 4);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-embedded-security-1', 'campaign-vec-embedded-security', 'trust-from-the-ground-up', 'Trust From the Ground Up', 'Threat modeling for devices, secure boot, firmware signing, device secrets, hardware root-of-trust and TLS on constrained devices.', 1),
  ('operation-vec-embedded-security-2', 'campaign-vec-embedded-security', 'the-counterfeit-controller', 'The Counterfeit Controller', 'Certificate provisioning, key rotation, debug-port risks, physical attack awareness, secure update pipelines, and the flagged device that fails every one of those checks.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-embedded-security-01', 'world-vec-embedded-security', 'campaign-vec-embedded-security', 'operation-vec-embedded-security-1', 'threat-model-for-devices', 'Threat Model for Devices', 'With the fleet finally visible, Vector Division starts the security audit Sera has been asking for since Act 9 -- and one device fails its very first check: its firmware does not match any signature Vector Division has ever issued.', 'beginner', ARRAY['imani','sera','byte'], null, null, '{"type":"simulation","simulationId":"threat-model-for-devices-sim"}'::jsonb, '{"xp":230,"credits":25}'::jsonb, false, 1),
  ('mission-vec-embedded-security-02', 'world-vec-embedded-security', 'campaign-vec-embedded-security', 'operation-vec-embedded-security-1', 'secure-boot', 'Secure Boot', 'A device that checks its own firmware before running it can refuse to run firmware nobody authorized. A device that does not check has already decided to trust whatever is present.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-embedded-security-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"secure-boot-sim"}'::jsonb, '{"xp":230,"credits":30}'::jsonb, false, 2),
  ('mission-vec-embedded-security-03', 'world-vec-embedded-security', 'campaign-vec-embedded-security', 'operation-vec-embedded-security-1', 'firmware-signing', 'Firmware Signing', 'A signature does not prove firmware is bug-free. It proves exactly one thing -- that whoever built it held the private key Vector Division controls, and nobody else does.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-embedded-security-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"firmware-signing-sim"}'::jsonb, '{"xp":240,"credits":30}'::jsonb, false, 3),
  ('mission-vec-embedded-security-04', 'world-vec-embedded-security', 'campaign-vec-embedded-security', 'operation-vec-embedded-security-1', 'device-secrets', 'Device Secrets', 'Every device on the fleet is supposed to carry a unique identity key, provisioned once and never shared -- because a secret baked identically into every unit is not really a secret at all.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-embedded-security-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"device-secrets-sim"}'::jsonb, '{"xp":240,"credits":35}'::jsonb, false, 4),
  ('mission-vec-embedded-security-05', 'world-vec-embedded-security', 'campaign-vec-embedded-security', 'operation-vec-embedded-security-1', 'hardware-root-of-trust', 'Hardware Root-of-Trust Concepts', 'Software can be reasoned about and rewritten. A root-of-trust cannot -- it is a small, fixed piece of hardware whose behavior nothing on the device, however compromised, is able to change.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-embedded-security-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"hardware-root-of-trust-sim"}'::jsonb, '{"xp":250,"credits":35}'::jsonb, false, 5),
  ('mission-vec-embedded-security-06', 'world-vec-embedded-security', 'campaign-vec-embedded-security', 'operation-vec-embedded-security-1', 'tls-on-constrained-devices', 'TLS on Constrained Devices', 'A full desktop TLS stack does not fit on a microcontroller with kilobytes of memory -- so a constrained device has to get the same guarantee, encrypted and authenticated, with a fraction of the room.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-embedded-security-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"tls-on-constrained-devices-sim"}'::jsonb, '{"xp":250,"credits":35}'::jsonb, false, 6),
  ('mission-vec-embedded-security-07', 'world-vec-embedded-security', 'campaign-vec-embedded-security', 'operation-vec-embedded-security-2', 'certificate-provisioning', 'Certificate Provisioning', 'A certificate is only as trustworthy as the process that issued it. Provisioning is that process -- and it is exactly the step Sera keeps insisting the fleet has never had.', 'beginner', ARRAY['sera','tomas'], '{"requiredMissionIds":["mission-vec-embedded-security-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"certificate-provisioning-sim"}'::jsonb, '{"xp":260,"credits":40}'::jsonb, false, 7),
  ('mission-vec-embedded-security-08', 'world-vec-embedded-security', 'campaign-vec-embedded-security', 'operation-vec-embedded-security-2', 'key-rotation', 'Key Rotation', 'A key that never changes is a key that, once exposed, stays exposed forever. Rotation is the plan for replacing a key before that exposure ever happens, not after.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-embedded-security-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"key-rotation-sim"}'::jsonb, '{"xp":260,"credits":40}'::jsonb, false, 8),
  ('mission-vec-embedded-security-09', 'world-vec-embedded-security', 'campaign-vec-embedded-security', 'operation-vec-embedded-security-2', 'debug-port-risks', 'Debug-Port Risks', 'The same debug port that lets an engineer flash and inspect a device at the factory does not stop working once the device ships -- it just stops being watched.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-embedded-security-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"debug-port-risks-sim"}'::jsonb, '{"xp":270,"credits":40}'::jsonb, false, 9),
  ('mission-vec-embedded-security-10', 'world-vec-embedded-security', 'campaign-vec-embedded-security', 'operation-vec-embedded-security-2', 'physical-attacks-awareness', 'Physical Attacks Awareness', 'Every guarantee this Act has taught assumes an attacker only reaches the device over a network. Sera''s job is to ask what happens once somebody can simply hold the board in their hands.', 'beginner', ARRAY['sera'], '{"requiredMissionIds":["mission-vec-embedded-security-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"physical-attacks-awareness-sim"}'::jsonb, '{"xp":270,"credits":45}'::jsonb, false, 10),
  ('mission-vec-embedded-security-11', 'world-vec-embedded-security', 'campaign-vec-embedded-security', 'operation-vec-embedded-security-2', 'secure-update-pipeline', 'Secure Update Pipeline', 'Every protection this Act built -- signing, provisioning, rotation -- is only as good as the pipeline that delivers it to a device already in the field.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-embedded-security-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"secure-update-pipeline-sim"}'::jsonb, '{"xp":280,"credits":45}'::jsonb, false, 11),
  ('mission-vec-embedded-security-12', 'world-vec-embedded-security', 'campaign-vec-embedded-security', 'operation-vec-embedded-security-2', 'the-counterfeit-controller', 'The Counterfeit Controller', 'One flagged device, every tool this Act built. Not an attack -- a process the fleet never had, finally made visible on the one board that slipped through decades ago.', 'boss', ARRAY['sera','tomas','byte','imani'], '{"requiredMissionIds":["mission-vec-embedded-security-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"counterfeit-controller-boss-sim"}'::jsonb, '{"xp":1200,"credits":250,"badgeIds":["the-counterfeit-controller"],"skillXp":{"robotics_fundamentals":155}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-embedded-security-01', 1, 'sera', 'I have been asking for a security audit of this fleet since Act 9. Now that Byte can actually see every matching controller across Nexus, we do not have an excuse left to delay it.'),
  ('mission-vec-embedded-security-01', 2, 'imani', 'Agreed. A fleet this size, all reachable at once, is also a fleet this size all attackable at once if Vector Division does not secure it first. Sera runs point on this Act.'),
  ('mission-vec-embedded-security-01', 3, 'byte', 'I am running the first pass against every device''s firmware signature now. Most match exactly what Vector Division has on file.'),
  ('mission-vec-embedded-security-01', 4, 'byte', 'One does not. A controller in the fleet is running firmware that does not match any signature we have ever issued. Not a known-old version, not a known-new one -- unrecognized entirely.'),
  ('mission-vec-embedded-security-01', 5, 'sera', 'That is exactly the kind of device this whole Act needs to teach you how to reason about, calmly and in order, before we go anywhere near it. Start with the threat model.'),

  ('mission-vec-embedded-security-02', 1, 'tomas', 'Secure boot means a device checks its own firmware before it ever executes a single instruction of it. Each stage of the boot chain verifies the next stage''s signature before handing off control.'),
  ('mission-vec-embedded-security-02', 2, 'byte', 'Without that check, a device will happily run whatever firmware is sitting in its flash memory -- authorized or not. Secure boot is the difference between a device that can refuse unauthorized code and one that never had the option.'),

  ('mission-vec-embedded-security-03', 1, 'tomas', 'Firmware signing does not certify that code is correct or bug-free. It certifies provenance -- that whoever produced this image held the private signing key, and that the image has not been altered since.'),
  ('mission-vec-embedded-security-03', 2, 'tomas', 'The device verifies with a public key baked in at manufacture. It never needs the private key, and it never should have it. If a private key ever leaves Vector Division''s signing server, every device trusting it needs a new one.'),

  ('mission-vec-embedded-security-04', 1, 'tomas', 'Every device needs a secret -- a key that proves its identity to the rest of the fleet. The rule is simple and constantly violated across the industry: unique per device, provisioned once, never logged, never shared.'),
  ('mission-vec-embedded-security-04', 2, 'byte', 'A shared secret baked identically into every unit of a product line is not a secret at all -- it is a single point of failure wearing a disguise. Extract it from one device and every device on the fleet is compromised at once.'),

  ('mission-vec-embedded-security-05', 1, 'tomas', 'A root-of-trust is the one piece of a device that cannot be reasoned with. It is small, fixed in hardware or immutable memory at manufacture, and nothing running on the device -- however deeply compromised -- can rewrite it.'),
  ('mission-vec-embedded-security-05', 2, 'tomas', 'Everything else -- secure boot, firmware signatures, device secrets -- ultimately has to anchor to that one unchangeable point, or none of it means anything. Trust has to start somewhere solid.'),

  ('mission-vec-embedded-security-06', 1, 'tomas', 'A desktop TLS stack assumes abundant memory and a fast processor. A constrained device has neither -- so it needs the same guarantee, encryption and authentication, built from lighter cryptography that fits in kilobytes.'),
  ('mission-vec-embedded-security-06', 2, 'byte', 'Which means "too small for security" was never actually true. It only meant too small for the desktop-sized implementation. The guarantee is the same; the tools to reach it are smaller.'),

  ('mission-vec-embedded-security-07', 1, 'sera', 'A certificate is only as trustworthy as the process that issued it. Provisioning is that process -- generating a device''s identity and certificate under controlled conditions, and recording that it happened.'),
  ('mission-vec-embedded-security-07', 2, 'tomas', 'Done right, every device that ever joins the fleet has a documented, auditable moment where it received its identity. No documented moment means no way to ever prove a device''s identity is legitimate.'),

  ('mission-vec-embedded-security-08', 1, 'tomas', 'No key stays secret forever. Rotation means replacing a key on a planned schedule, before any known exposure -- so a compromise, if it ever happens, only affects a limited window instead of a key''s entire lifetime.'),
  ('mission-vec-embedded-security-08', 2, 'tomas', 'A fleet that has never rotated a single key is a fleet betting that no key has ever leaked. That is not a security posture. That is hope.'),

  ('mission-vec-embedded-security-09', 1, 'tomas', 'Every device on this fleet shipped with a debug port -- the same interface engineers used to flash and inspect it at the factory. Shipping does not disable it. It just stops anyone from watching who uses it next.'),
  ('mission-vec-embedded-security-09', 2, 'byte', 'An open debug port on a fielded device can let anyone with physical access read out firmware, extract secrets, or reflash it entirely -- no network involved at all.'),

  ('mission-vec-embedded-security-10', 1, 'sera', 'Every guarantee this Act has built so far assumes an attacker only ever reaches a device over a network. My job is to ask the question nobody else on this team likes asking: what happens once someone can simply hold the board?'),
  ('mission-vec-embedded-security-10', 2, 'sera', 'Physical access changes the threat model completely. Someone can probe traces directly, desolder a chip, or read memory a network attacker could never touch. Physical security is not optional just because it is inconvenient.'),

  ('mission-vec-embedded-security-11', 1, 'tomas', 'Signing, provisioning, rotation -- every protection this Act built only matters if it can actually reach a device already deployed in the field. That delivery path is the update pipeline.'),
  ('mission-vec-embedded-security-11', 2, 'byte', 'A secure pipeline verifies the update''s signature before applying it, keeps a known-good version to roll back to if the update fails, and never lets a device apply an image it cannot verify -- no matter how the image arrived.'),

  ('mission-vec-embedded-security-12', 1, 'sera', 'This is the device I flagged from Mission 1. Every tool this Act built, we use right now, on this one board -- not to assign blame, but to actually understand what we are looking at.'),
  ('mission-vec-embedded-security-12', 2, 'tomas', 'Its firmware does not match any signature Vector Division has ever issued. Not an old version we forgot about -- unsigned, or signed by a key that was never ours.'),
  ('mission-vec-embedded-security-12', 3, 'byte', 'And it gets stranger. I checked its device identity against provisioning records. This board was never provisioned at all. There is no record of it ever receiving a unique key from us, ever.'),
  ('mission-vec-embedded-security-12', 4, 'tomas', 'Because it is not our board. Pull the physical unit and look -- this is a generic, off-the-shelf replacement part. Installed by a maintenance technician decades ago, after the original failed, running unofficial firmware close enough to normal behavior that nothing ever flagged it until today.'),
  ('mission-vec-embedded-security-12', 5, 'sera', 'Nobody attacked this device. Nobody had to. Nobody ever enforced a process that could have caught an unsigned, unauthorized replacement part in the first place -- and that gap is exactly what I have been asking this team to close since Act 9.'),
  ('mission-vec-embedded-security-12', 6, 'sera', 'Most of the fleet is bare-metal firmware we can now secure end to end, the way we just secured this diagnosis. A handful of facility gateways run something different -- embedded Linux -- and that needs its own review.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-embedded-security-01-o1', 'mission-vec-embedded-security-01', 1, 'Build the threat model', 'Sort each fleet risk into the correct threat category before assuming the flagged device is any one of them.'),
  ('mission-vec-embedded-security-01-o2', 'mission-vec-embedded-security-01', 2, 'Judge the first signal', 'Based on Byte''s scan, judge what an unrecognized firmware signature most likely means.'),

  ('mission-vec-embedded-security-02-o1', 'mission-vec-embedded-security-02', 1, 'Order the boot chain', 'Order secure boot''s verification chain from power-on to application code.'),
  ('mission-vec-embedded-security-02-o2', 'mission-vec-embedded-security-02', 2, 'Judge a boot failure', 'Judge what should happen when a stage fails to verify the next stage''s signature.'),

  ('mission-vec-embedded-security-03-o1', 'mission-vec-embedded-security-03', 1, 'Define what a signature proves', 'Choose the accurate description of what firmware signing actually guarantees.'),
  ('mission-vec-embedded-security-03-o2', 'mission-vec-embedded-security-03', 2, 'Find the key exposure', 'Find the evidence describing a signing-key handling mistake that would compromise the fleet.'),

  ('mission-vec-embedded-security-04-o1', 'mission-vec-embedded-security-04', 1, 'Sort the secrets', 'Sort each device-secret practice into safe or unsafe.'),
  ('mission-vec-embedded-security-04-o2', 'mission-vec-embedded-security-04', 2, 'Explain the shared-secret risk', 'State why a secret shared identically across a whole product line is not really a secret.'),

  ('mission-vec-embedded-security-05-o1', 'mission-vec-embedded-security-05', 1, 'Define root-of-trust', 'Choose the accurate description of what a hardware root-of-trust provides.'),
  ('mission-vec-embedded-security-05-o2', 'mission-vec-embedded-security-05', 2, 'Trace the anchor', 'Find the evidence showing a device''s secure boot chain ultimately anchors to its root-of-trust.'),

  ('mission-vec-embedded-security-06-o1', 'mission-vec-embedded-security-06', 1, 'Explain the constraint', 'Choose the accurate reason constrained devices cannot run a full desktop TLS stack.'),
  ('mission-vec-embedded-security-06-o2', 'mission-vec-embedded-security-06', 2, 'Judge the guarantee', 'Judge whether a lightweight TLS implementation on a constrained device still provides the same core guarantee.'),

  ('mission-vec-embedded-security-07-o1', 'mission-vec-embedded-security-07', 1, 'Order provisioning', 'Order the steps of a correct certificate provisioning process.'),
  ('mission-vec-embedded-security-07-o2', 'mission-vec-embedded-security-07', 2, 'Spot the missing record', 'Find the evidence showing a device with no provisioning record at all.'),

  ('mission-vec-embedded-security-08-o1', 'mission-vec-embedded-security-08', 1, 'Explain rotation''s purpose', 'Choose the accurate reason for rotating keys on a schedule rather than only after a known compromise.'),
  ('mission-vec-embedded-security-08-o2', 'mission-vec-embedded-security-08', 2, 'Judge a fleet''s posture', 'Given a fleet''s key history, judge whether its rotation practice is adequate.'),

  ('mission-vec-embedded-security-09-o1', 'mission-vec-embedded-security-09', 1, 'Sort the debug-port states', 'Sort each device configuration into safe or risky debug-port handling.'),
  ('mission-vec-embedded-security-09-o2', 'mission-vec-embedded-security-09', 2, 'Judge the exposure', 'Judge what an open, unauthenticated debug port on a fielded device actually exposes.'),

  ('mission-vec-embedded-security-10-o1', 'mission-vec-embedded-security-10', 1, 'Define the physical threat model', 'Choose the accurate description of how physical access changes an attacker''s capabilities.'),
  ('mission-vec-embedded-security-10-o2', 'mission-vec-embedded-security-10', 2, 'Find the physical exposure', 'Find the evidence describing a device left exposed to physical tampering.'),

  ('mission-vec-embedded-security-11-o1', 'mission-vec-embedded-security-11', 1, 'Order the pipeline', 'Order a secure update pipeline''s steps from signing to a device applying the update.'),
  ('mission-vec-embedded-security-11-o2', 'mission-vec-embedded-security-11', 2, 'Judge a broken pipeline', 'Find the evidence showing an update pipeline step that would let an unverified image reach a device.'),

  ('mission-vec-embedded-security-12-o1', 'mission-vec-embedded-security-12', 1, 'Rule out a legitimate old version', 'Using firmware-signing and secure-boot reasoning, judge whether the flagged device''s image could just be a legitimate but outdated version.'),
  ('mission-vec-embedded-security-12-o2', 'mission-vec-embedded-security-12', 2, 'Trace the missing hardware identity', 'Using device-secrets and provisioning reasoning, find the evidence proving the board itself lacks the expected hardware identity entirely.'),
  ('mission-vec-embedded-security-12-o3', 'mission-vec-embedded-security-12', 3, 'Classify the incident', 'Using threat-model reasoning, judge whether this is a supply-chain/process gap or an active attack.'),
  ('mission-vec-embedded-security-12-o4', 'mission-vec-embedded-security-12', 4, 'State the diagnosis and the fix', 'Having ruled out a legitimate version, traced the missing identity, and classified the incident, state what the device actually is and the process fix that would have caught it.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-embedded-security-01-o1-c1', 'mission-vec-embedded-security-01-o1', 1, 'drag_and_drop', 'Sort each fleet risk into the threat category it belongs to.', '{"items":[{"id":"i1","text":"An attacker on the same network sending forged commands to a controller"},{"id":"i2","text":"A technician plugging a laptop directly into a device''s exposed debug port"},{"id":"i3","text":"A firmware update server being tricked into signing a malicious image"},{"id":"i4","text":"An unsigned replacement board installed without any identity ever being issued to it"}],"targets":[{"id":"network","label":"Network-based threat"},{"id":"physical","label":"Physical-access threat"},{"id":"supply-chain","label":"Supply-chain / process threat"}]}'::jsonb, '{"correctMapping":{"i1":"network","i2":"physical","i3":"supply-chain","i4":"supply-chain"}}'::jsonb),
  ('mission-vec-embedded-security-01-o2-c1', 'mission-vec-embedded-security-01-o2', 1, 'multiple_choice', 'A device''s firmware signature matches no signature Vector Division has ever issued -- not an old one, not a new one. What does that most likely mean, before any further investigation?', '{"question":"A device''s firmware signature matches no signature Vector Division has ever issued -- not an old one, not a new one. What does that most likely mean, before any further investigation?","options":[{"id":"a","text":"The device is definitely running malware planted by an attacker"},{"id":"b","text":"The device is running an image Vector Division never produced, which could mean a compromise, an unofficial replacement, or a process gap -- it rules nothing in or out yet"},{"id":"c","text":"It is a harmless logging glitch and can be ignored"},{"id":"d","text":"It means the device is simply offline"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-embedded-security-02-o1-c1', 'mission-vec-embedded-security-02-o1', 1, 'interactive_diagram', 'Order secure boot''s verification chain from power-on to application code.', '{"diagramId":"secure-boot-chain","hotspots":[{"id":"rom","label":"Immutable boot ROM","explanation":"Fixed at manufacture, this first stage cannot be modified and verifies the next stage before running it."},{"id":"bootloader","label":"Bootloader","explanation":"Verified by the ROM, it in turn verifies the firmware image before handing off control."},{"id":"firmware","label":"Firmware image","explanation":"Verified by the bootloader, this is the operating logic the device actually runs."},{"id":"application","label":"Application code","explanation":"Runs only after every earlier stage has verified successfully."}],"task":"Order the stages of the secure boot chain from power-on to application code."}'::jsonb, '{"correctOrderIds":["rom","bootloader","firmware","application"]}'::jsonb),
  ('mission-vec-embedded-security-02-o2-c1', 'mission-vec-embedded-security-02-o2', 1, 'multiple_choice', 'A boot stage checks the next stage''s signature and it fails to verify. What should a correctly implemented secure boot do?', '{"question":"A boot stage checks the next stage''s signature and it fails to verify. What should a correctly implemented secure boot do?","options":[{"id":"a","text":"Run the unverified stage anyway and log a warning"},{"id":"b","text":"Halt the boot process and refuse to execute the unverified stage at all"},{"id":"c","text":"Skip that stage and boot directly into the application code"},{"id":"d","text":"Silently retry the same unverified stage until it eventually succeeds"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-embedded-security-03-o1-c1', 'mission-vec-embedded-security-03-o1', 1, 'multiple_choice', 'A valid firmware signature proves...', '{"question":"A valid firmware signature proves...","options":[{"id":"a","text":"The firmware is free of bugs and vulnerabilities"},{"id":"b","text":"The image was produced by whoever holds the private signing key, and has not been altered since it was signed"},{"id":"c","text":"The firmware has been tested on every device model"},{"id":"d","text":"The device that receives it is free of malware"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-embedded-security-03-o2-c1', 'mission-vec-embedded-security-03-o2', 1, 'investigation', 'Which piece of evidence describes a signing-key handling mistake that would compromise the whole fleet?', '{"evidence":[{"id":"e1","label":"Build log","detail":"The signing server produced a new firmware image and signed it with the standard private key"},{"id":"e2","label":"Incident note","detail":"A contractor copied the private signing key onto a personal laptop for offline testing"},{"id":"e3","label":"Device log","detail":"A single device rejected an image with an invalid signature and refused to boot it"}],"question":"Which piece of evidence describes a signing-key handling mistake that would compromise the whole fleet?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-embedded-security-04-o1-c1', 'mission-vec-embedded-security-04-o1', 1, 'drag_and_drop', 'Sort each device-secret practice into safe or unsafe.', '{"items":[{"id":"d1","text":"Every unit of a product line ships with the exact same hardcoded key"},{"id":"d2","text":"Each device receives a unique key generated and injected during a controlled provisioning step"},{"id":"d3","text":"A device''s unique key is written to a build log accessible to the whole engineering team"},{"id":"d4","text":"A device''s unique key is stored only inside protected hardware storage on that device"}],"targets":[{"id":"safe","label":"Safe"},{"id":"unsafe","label":"Unsafe"}]}'::jsonb, '{"correctMapping":{"d1":"unsafe","d2":"safe","d3":"unsafe","d4":"safe"}}'::jsonb),
  ('mission-vec-embedded-security-04-o2-c1', 'mission-vec-embedded-security-04-o2', 1, 'multiple_choice', 'Why is a secret shared identically across an entire product line not really a secret at all?', '{"question":"Why is a secret shared identically across an entire product line not really a secret at all?","options":[{"id":"a","text":"Shared secrets are always weaker cryptographically than unique ones"},{"id":"b","text":"Extracting it from a single unit compromises every device in the fleet at once, since the same value authenticates all of them"},{"id":"c","text":"Shared secrets take longer to generate"},{"id":"d","text":"It is only a problem if the product line is very large"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-embedded-security-05-o1-c1', 'mission-vec-embedded-security-05-o1', 1, 'multiple_choice', 'A hardware root-of-trust provides...', '{"question":"A hardware root-of-trust provides...","options":[{"id":"a","text":"A software setting that can be reconfigured remotely at any time"},{"id":"b","text":"A small, fixed piece of hardware or immutable memory that nothing running on the device, however compromised, can rewrite -- the fixed point everything else anchors to"},{"id":"c","text":"An optional convenience feature with no security purpose"},{"id":"d","text":"A backup copy of the device''s firmware"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-embedded-security-05-o2-c1', 'mission-vec-embedded-security-05-o2', 1, 'investigation', 'Which evidence shows a device''s secure boot chain ultimately anchors to its root-of-trust?', '{"evidence":[{"id":"e1","label":"Design note","detail":"The boot ROM''s first verification key is burned into one-time-programmable memory at manufacture and can never be altered afterward"},{"id":"e2","label":"Facilities note","detail":"The device housing is rated for outdoor use"},{"id":"e3","label":"Power log","detail":"The device draws a stable current at idle"}],"question":"Which evidence shows a device''s secure boot chain ultimately anchors to its root-of-trust?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-embedded-security-06-o1-c1', 'mission-vec-embedded-security-06-o1', 1, 'multiple_choice', 'Why can a constrained device not simply run a standard desktop TLS stack unmodified?', '{"question":"Why can a constrained device not simply run a standard desktop TLS stack unmodified?","options":[{"id":"a","text":"TLS was never designed to work on any embedded hardware"},{"id":"b","text":"A desktop TLS stack assumes far more memory and processing power than a microcontroller has available, so a constrained device needs lighter cryptographic building blocks to reach the same guarantee"},{"id":"c","text":"Constrained devices are physically incapable of encryption"},{"id":"d","text":"TLS requires a keyboard and cannot run headless"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-embedded-security-06-o2-c1', 'mission-vec-embedded-security-06-o2', 1, 'multiple_choice', 'A constrained device uses a lightweight TLS implementation with smaller cryptographic primitives suited to its memory budget. Does it still provide the same core guarantee as a full desktop TLS stack?', '{"question":"A constrained device uses a lightweight TLS implementation with smaller cryptographic primitives suited to its memory budget. Does it still provide the same core guarantee as a full desktop TLS stack?","options":[{"id":"a","text":"No, lightweight implementations cannot provide real encryption or authentication"},{"id":"b","text":"Yes -- properly implemented, it still provides encrypted, authenticated communication, just using cryptography sized to fit the device''s constraints"},{"id":"c","text":"Only if the device is connected to a wired network"},{"id":"d","text":"Only authentication is possible, never encryption, on constrained hardware"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-embedded-security-07-o1-c1', 'mission-vec-embedded-security-07-o1', 1, 'interactive_diagram', 'Order the steps of a correct certificate provisioning process.', '{"diagramId":"certificate-provisioning-steps","hotspots":[{"id":"identity","label":"Generate a unique device identity","explanation":"A unique key pair is generated for this specific device, not reused from another."},{"id":"sign","label":"Sign a certificate for that identity","explanation":"Vector Division''s certificate authority signs a certificate binding that identity to this device."},{"id":"inject","label":"Inject the certificate under controlled conditions","explanation":"The certificate is written to the device during a documented manufacturing or provisioning step."},{"id":"record","label":"Record the provisioning event","explanation":"The event is logged so the device''s legitimate identity can later be audited and confirmed."}],"task":"Order the steps of certificate provisioning from generating an identity to recording the event."}'::jsonb, '{"correctOrderIds":["identity","sign","inject","record"]}'::jsonb),
  ('mission-vec-embedded-security-07-o2-c1', 'mission-vec-embedded-security-07-o2', 1, 'investigation', 'Which evidence shows a device with no provisioning record at all?', '{"evidence":[{"id":"e1","label":"Provisioning database query","detail":"A search for the flagged device''s serial number and identity key returns zero matching records anywhere in the provisioning history"},{"id":"e2","label":"Facilities note","detail":"The device is installed in a facility gateway rack"},{"id":"e3","label":"Power log","detail":"The device has been drawing power continuously for several years"}],"question":"Which evidence shows a device with no provisioning record at all?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-embedded-security-08-o1-c1', 'mission-vec-embedded-security-08-o1', 1, 'multiple_choice', 'Why rotate keys on a planned schedule instead of only after a known compromise?', '{"question":"Why rotate keys on a planned schedule instead of only after a known compromise?","options":[{"id":"a","text":"Scheduled rotation is purely a compliance formality with no real security benefit"},{"id":"b","text":"Because an undetected compromise can go unnoticed for a long time -- scheduled rotation limits how long any single exposed key stays useful to an attacker, known or not"},{"id":"c","text":"Rotating keys makes them cryptographically stronger over time"},{"id":"d","text":"Keys physically wear out and need periodic replacement like a battery"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-embedded-security-08-o2-c1', 'mission-vec-embedded-security-08-o2', 1, 'multiple_choice', 'A fleet has used the same device keys, unrotated, since the fleet was first deployed years ago, with no rotation plan in place. Is that an adequate security posture?', '{"question":"A fleet has used the same device keys, unrotated, since the fleet was first deployed years ago, with no rotation plan in place. Is that an adequate security posture?","options":[{"id":"a","text":"Yes, as long as no compromise has been detected so far"},{"id":"b","text":"No -- with no rotation plan, any undetected key exposure at any point in that entire history remains exploitable indefinitely"},{"id":"c","text":"Yes, because keys never actually need to be rotated once issued"},{"id":"d","text":"It cannot be judged without knowing the exact key length"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-embedded-security-09-o1-c1', 'mission-vec-embedded-security-09-o1', 1, 'drag_and_drop', 'Sort each device configuration into safe or risky debug-port handling.', '{"items":[{"id":"g1","text":"Debug port left fully enabled and unauthenticated on a fielded, shipped device"},{"id":"g2","text":"Debug port disabled by a fuse blown at end of manufacturing, permanently unavailable afterward"},{"id":"g3","text":"Debug port requires a cryptographic challenge-response before granting any access"},{"id":"g4","text":"Debug port physically accessible through an unlabeled header on the outside of the enclosure"}],"targets":[{"id":"safe","label":"Safe"},{"id":"risky","label":"Risky"}]}'::jsonb, '{"correctMapping":{"g1":"risky","g2":"safe","g3":"safe","g4":"risky"}}'::jsonb),
  ('mission-vec-embedded-security-09-o2-c1', 'mission-vec-embedded-security-09-o2', 1, 'multiple_choice', 'What does an open, unauthenticated debug port on a fielded device actually expose?', '{"question":"What does an open, unauthenticated debug port on a fielded device actually expose?","options":[{"id":"a","text":"Nothing, debug ports are only usable during manufacturing"},{"id":"b","text":"Anyone with physical access can read out firmware, extract stored secrets, or reflash the device entirely -- with no network involved"},{"id":"c","text":"Only cosmetic diagnostic information with no security value"},{"id":"d","text":"It only matters if the device is also connected to a network"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-embedded-security-10-o1-c1', 'mission-vec-embedded-security-10-o1', 1, 'multiple_choice', 'How does physical access change what an attacker can do compared to a purely network-based attacker?', '{"question":"How does physical access change what an attacker can do compared to a purely network-based attacker?","options":[{"id":"a","text":"It does not change anything meaningfully"},{"id":"b","text":"A physically present attacker can probe circuit traces directly, desolder chips, or read memory in ways a network attacker never could -- defenses that only assume network access are incomplete"},{"id":"c","text":"Physical access only matters for very expensive, rare hardware"},{"id":"d","text":"Physical attacks are always harder to execute than network attacks"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-embedded-security-10-o2-c1', 'mission-vec-embedded-security-10-o2', 1, 'investigation', 'Which evidence describes a device left exposed to physical tampering?', '{"evidence":[{"id":"e1","label":"Facilities note","detail":"A gateway device sits in an unlocked equipment closet with public corridor access and no tamper-evident seal"},{"id":"e2","label":"Network log","detail":"The device''s network traffic is fully encrypted end to end"},{"id":"e3","label":"Build log","detail":"The device''s firmware was signed correctly before deployment"}],"question":"Which evidence describes a device left exposed to physical tampering?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-embedded-security-11-o1-c1', 'mission-vec-embedded-security-11-o1', 1, 'interactive_diagram', 'Order a secure update pipeline''s steps from signing to a device applying the update.', '{"diagramId":"secure-update-pipeline-steps","hotspots":[{"id":"build","label":"Build the update image","explanation":"A new firmware image is compiled from reviewed source."},{"id":"sign","label":"Sign the image","explanation":"The signing server signs the image with the fleet''s private key."},{"id":"deliver","label":"Deliver the image to the device","explanation":"The signed image is transmitted to the device over the update channel."},{"id":"verify","label":"Device verifies the signature","explanation":"The device checks the signature before ever applying the update."},{"id":"apply","label":"Apply the update, with rollback ready","explanation":"The device applies the verified update, keeping a known-good version to roll back to if it fails."}],"task":"Order the steps of a secure update pipeline from building the image to the device applying it."}'::jsonb, '{"correctOrderIds":["build","sign","deliver","verify","apply"]}'::jsonb),
  ('mission-vec-embedded-security-11-o2-c1', 'mission-vec-embedded-security-11-o2', 1, 'investigation', 'Which evidence shows an update pipeline step that would let an unverified image reach a device?', '{"evidence":[{"id":"e1","label":"Pipeline config","detail":"A device''s update client is configured to apply any image received on the update channel without checking a signature first"},{"id":"e2","label":"Build log","detail":"The signing server correctly signed the latest firmware image"},{"id":"e3","label":"Rollback log","detail":"A device successfully rolled back to its previous known-good version after a failed update"}],"question":"Which evidence shows an update pipeline step that would let an unverified image reach a device?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-embedded-security-12-o1-c1', 'mission-vec-embedded-security-12-o1', 1, 'multiple_choice', 'The flagged device''s firmware matches no signature Vector Division has ever issued, old or new. Could this still just be a legitimate but outdated version?', '{"question":"The flagged device''s firmware matches no signature Vector Division has ever issued, old or new. Could this still just be a legitimate but outdated version?","options":[{"id":"a","text":"Yes, old firmware versions commonly fail signature checks"},{"id":"b","text":"No -- a legitimate outdated version would still match a signature Vector Division actually issued at some point; matching none at all rules that explanation out"},{"id":"c","text":"It cannot be determined without physically opening the device"},{"id":"d","text":"Yes, because secure boot only checks the newest version"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-embedded-security-12-o2-c1', 'mission-vec-embedded-security-12-o2', 1, 'investigation', 'Which evidence proves the board itself lacks the expected hardware identity entirely, rather than just running unexpected firmware?', '{"evidence":[{"id":"e1","label":"Provisioning database query","detail":"A search for this device''s serial number and identity key returns zero matching records anywhere in provisioning history -- it was never issued a Vector Division device identity at all"},{"id":"e2","label":"Firmware signature check","detail":"The firmware image does not match any signature Vector Division has issued"},{"id":"e3","label":"Power log","detail":"The device draws power within a normal operating range"}],"question":"Which evidence proves the board itself lacks the expected hardware identity entirely, rather than just running unexpected firmware?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-embedded-security-12-o3-c1', 'mission-vec-embedded-security-12-o3', 1, 'multiple_choice', 'Putting the unrecognized signature and the missing provisioning record together, what kind of incident is this?', '{"question":"Putting the unrecognized signature and the missing provisioning record together, what kind of incident is this?","options":[{"id":"a","text":"An active network attacker currently exploiting the device"},{"id":"b","text":"A supply-chain and process gap -- a good-faith hardware replacement that was never provisioned or signed, not an attack in progress"},{"id":"c","text":"A random hardware failure with no security relevance"},{"id":"d","text":"Proof of a compromised signing key affecting the whole fleet"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-embedded-security-12-o4-c1', 'mission-vec-embedded-security-12-o4', 1, 'boss_encounter', 'Having ruled out a legitimate version, traced the missing hardware identity, and classified the incident, state what the device actually is and the process fix that would have caught it.', '{"stages":[{"objectiveRef":"mission-vec-embedded-security-12-o1","label":"Rule out a legitimate old version"},{"objectiveRef":"mission-vec-embedded-security-12-o2","label":"Trace the missing hardware identity"},{"objectiveRef":"mission-vec-embedded-security-12-o3","label":"Classify the incident"}],"task":"State the diagnosis in one sentence: the board is a generic, off-the-shelf replacement part installed by a maintenance technician decades ago after the original failed, running unofficial firmware close enough to normal behavior that nothing ever flagged it -- and state the fix, that every replacement part must be provisioned and signed before it is ever returned to service."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-embedded-security-12-o1","mission-vec-embedded-security-12-o2","mission-vec-embedded-security-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-embedded-security-01-o1-c1', 'orientation', 'Ask where the attacker would have to stand: on the network, physically at the device, or nowhere near it at all because the gap is in a process.', 10, 1),
  ('mission-vec-embedded-security-01-o1-c1', 'solution', 'Network: forged commands over the network. Physical: a laptop plugged into a debug port. Supply-chain: a tricked signing server and an unsigned replacement board with no issued identity.', 20, 2),
  ('mission-vec-embedded-security-01-o2-c1', 'orientation', 'An unrecognized signature is a fact, not yet a conclusion -- resist naming a cause before investigating.', 10, 1),
  ('mission-vec-embedded-security-01-o2-c1', 'solution', 'It only proves the image was not one Vector Division produced -- compromise, unofficial replacement, and process gap are all still open until more evidence narrows it down.', 20, 2),

  ('mission-vec-embedded-security-02-o1-c1', 'orientation', 'Each stage has to check the next one before handing off control -- nothing can verify itself.', 10, 1),
  ('mission-vec-embedded-security-02-o1-c1', 'solution', 'The immutable boot ROM verifies the bootloader, the bootloader verifies the firmware image, and only then does application code run.', 20, 2),
  ('mission-vec-embedded-security-02-o2-c1', 'orientation', 'Ask what "secure" would mean if the device just kept going anyway after a failed check.', 10, 1),
  ('mission-vec-embedded-security-02-o2-c1', 'solution', 'It should halt and refuse to execute the unverified stage -- continuing anyway defeats the entire purpose of the check.', 20, 2),

  ('mission-vec-embedded-security-03-o1-c1', 'orientation', 'A signature is about who produced something and whether it changed since, not about the quality of what is inside it.', 10, 1),
  ('mission-vec-embedded-security-03-o1-c1', 'solution', 'It proves provenance and integrity -- produced by the private key holder, unaltered since signing -- not correctness or safety.', 20, 2),
  ('mission-vec-embedded-security-03-o2-c1', 'orientation', 'Look for evidence about where the private key itself ended up, not about a normal signing operation.', 10, 1),
  ('mission-vec-embedded-security-03-o2-c1', 'solution', 'e2: copying the private signing key onto a personal laptop is the mistake that would let anyone with that laptop sign firmware the whole fleet would trust.', 20, 2),

  ('mission-vec-embedded-security-04-o1-c1', 'orientation', 'Ask whether the practice makes each device individually identifiable, or interchangeable with every other unit.', 10, 1),
  ('mission-vec-embedded-security-04-o1-c1', 'solution', 'Unsafe: an identical hardcoded key across the line, and a key exposed in an accessible build log. Safe: a unique key per device from controlled provisioning, stored in protected hardware.', 20, 2),
  ('mission-vec-embedded-security-04-o2-c1', 'orientation', 'Think about what happens once one device is compromised, if every device shares the same value.', 10, 1),
  ('mission-vec-embedded-security-04-o2-c1', 'solution', 'Extracting the secret from a single unit compromises the identity of every device that shares it -- a shared secret is only ever as strong as its weakest exposed copy.', 20, 2),

  ('mission-vec-embedded-security-05-o1-c1', 'orientation', 'Ask what stays true even if every line of software on the device has already been compromised.', 10, 1),
  ('mission-vec-embedded-security-05-o1-c1', 'solution', 'A root-of-trust is fixed hardware or immutable memory that nothing on the device, however compromised, can rewrite -- the one fixed anchor point for everything else.', 20, 2),
  ('mission-vec-embedded-security-05-o2-c1', 'orientation', 'Look for evidence about a key or value that is physically impossible to change after manufacture.', 10, 1),
  ('mission-vec-embedded-security-05-o2-c1', 'solution', 'e1: a verification key burned into one-time-programmable memory at manufacture is exactly the fixed anchor the rest of the boot chain relies on.', 20, 2),

  ('mission-vec-embedded-security-06-o1-c1', 'orientation', 'Ask what resource a microcontroller actually lacks compared to a desktop, not whether TLS itself is possible.', 10, 1),
  ('mission-vec-embedded-security-06-o1-c1', 'solution', 'A desktop TLS stack assumes far more memory and compute than a microcontroller has, so constrained devices need lighter cryptography sized to what they actually have available.', 20, 2),
  ('mission-vec-embedded-security-06-o2-c1', 'orientation', 'Smaller does not mean weaker in principle -- ask whether the same properties, encryption and authentication, are still present.', 10, 1),
  ('mission-vec-embedded-security-06-o2-c1', 'solution', 'Yes -- a properly implemented lightweight stack still delivers encrypted, authenticated communication, just with primitives sized to the device''s constraints.', 20, 2),

  ('mission-vec-embedded-security-07-o1-c1', 'orientation', 'An identity has to exist before it can be certified, and it has to be certified before it can be installed.', 10, 1),
  ('mission-vec-embedded-security-07-o1-c1', 'solution', 'Generate the unique identity, sign a certificate for it, inject it under controlled conditions, and record the event.', 20, 2),
  ('mission-vec-embedded-security-07-o2-c1', 'orientation', 'Look for a direct database query result, not a note about where the device is installed.', 10, 1),
  ('mission-vec-embedded-security-07-o2-c1', 'solution', 'e1: zero matching provisioning records for this device''s serial number and identity key means it was never provisioned at all.', 20, 2),

  ('mission-vec-embedded-security-08-o1-c1', 'orientation', 'Think about how long an exposure could last if nobody ever plans to change the key.', 10, 1),
  ('mission-vec-embedded-security-08-o1-c1', 'solution', 'Scheduled rotation limits how long any single exposed key, detected or not, stays useful to an attacker -- it does not depend on already knowing about a compromise.', 20, 2),
  ('mission-vec-embedded-security-08-o2-c1', 'orientation', '"No known compromise" is not the same as "no compromise happened."', 10, 1),
  ('mission-vec-embedded-security-08-o2-c1', 'solution', 'No, it is not adequate -- with no rotation plan, any undetected exposure at any point in the fleet''s history remains exploitable indefinitely.', 20, 2),

  ('mission-vec-embedded-security-09-o1-c1', 'orientation', 'Ask whether the port requires proof of authorization, or whether anyone who finds it can simply use it.', 10, 1),
  ('mission-vec-embedded-security-09-o1-c1', 'solution', 'Risky: fully open and unauthenticated on a fielded device, and an unlabeled but physically accessible header. Safe: permanently fused off, or gated behind a cryptographic challenge.', 20, 2),
  ('mission-vec-embedded-security-09-o2-c1', 'orientation', 'A debug port''s whole purpose during manufacturing is deep, unrestricted access -- ask what that means once it ships still open.', 10, 1),
  ('mission-vec-embedded-security-09-o2-c1', 'solution', 'It exposes firmware readout, secret extraction, and full reflashing to anyone with physical access, entirely independent of network security.', 20, 2),

  ('mission-vec-embedded-security-10-o1-c1', 'orientation', 'Ask what becomes reachable once an attacker no longer has to go through the network interface at all.', 10, 1),
  ('mission-vec-embedded-security-10-o1-c1', 'solution', 'Physical access opens direct trace probing, desoldering, and memory extraction -- capabilities purely network-based defenses were never designed to stop.', 20, 2),
  ('mission-vec-embedded-security-10-o2-c1', 'orientation', 'Look for a note about the physical location and access control around the device, not its network or firmware state.', 10, 1),
  ('mission-vec-embedded-security-10-o2-c1', 'solution', 'e1: an unlocked closet with public corridor access and no tamper-evident seal leaves the device open to anyone who walks up to it.', 20, 2),

  ('mission-vec-embedded-security-11-o1-c1', 'orientation', 'Nothing can be verified before it exists, and nothing can be applied before it is verified.', 10, 1),
  ('mission-vec-embedded-security-11-o1-c1', 'solution', 'Build the image, sign it, deliver it to the device, have the device verify the signature, then apply it with rollback ready.', 20, 2),
  ('mission-vec-embedded-security-11-o2-c1', 'orientation', 'Look for the step where a check is supposed to happen but was configured away entirely.', 10, 1),
  ('mission-vec-embedded-security-11-o2-c1', 'solution', 'e1: a device configured to apply any image without checking a signature first is exactly the gap that lets an unverified image through.', 20, 2),

  ('mission-vec-embedded-security-12-o1-c1', 'orientation', 'Think back to what a legitimate outdated version would still have, even if it is old.', 10, 1),
  ('mission-vec-embedded-security-12-o1-c1', 'solution', 'No -- a legitimate old version would still match some signature Vector Division actually issued in the past. Matching none rules that explanation out entirely.', 20, 2),
  ('mission-vec-embedded-security-12-o2-c1', 'orientation', 'You have seen this exact kind of evidence before, in Mission 7.', 10, 1),
  ('mission-vec-embedded-security-12-o2-c1', 'solution', 'e1: zero provisioning records means this board was never issued a Vector Division device identity at all -- it is not a compromised original, it never had our identity to begin with.', 20, 2),
  ('mission-vec-embedded-security-12-o3-c1', 'orientation', 'Combine what is missing (identity) with what is present (a working, if unofficial, replacement) to judge intent.', 10, 1),
  ('mission-vec-embedded-security-12-o3-c1', 'solution', 'It is a supply-chain and process gap -- a good-faith hardware replacement that skipped provisioning and signing, not an attacker currently exploiting the device.', 20, 2),
  ('mission-vec-embedded-security-12-o4-c1', 'orientation', 'State plainly what the board is, why it slipped through, and what step would have stopped it.', 15, 1),
  ('mission-vec-embedded-security-12-o4-c1', 'solution', 'The board is a generic, off-the-shelf replacement part installed by a maintenance technician decades ago, running unofficial firmware close enough to normal that nothing flagged it -- the fix is that every replacement part must be provisioned and signed before it returns to service.', 25, 2);
